import { test, expect } from '@playwright/test';

test.describe('Search Term Exclusion by Prefixing with "-"', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should exclude a search term when prefixed with "-" and display relevant results', async ({ page }) => {
    // Verify search input is visible
    const searchInput = page.getByPlaceholder('Search...');
    await expect(searchInput).toBeVisible();

    // Perform search with exclusion
    await searchInput.fill('laptop -brand');

    // Wait for search results to load
    await page.waitForResponse(response => 
      response.url().includes('/api/search') && response.status() === 200
    );

    // Verify search results container is visible
    const resultsContainer = page.getByRole('region', { name: /search results/i });
    await expect(resultsContainer).toBeVisible();

    // Verify results are displayed
    const resultItems = page.getByRole('listitem');
    await expect(resultItems).toHaveCount(1);

    // Verify the result contains the search term but not the excluded brand
    const resultText = await resultItems.first().textContent();
    expect(resultText).toContain('laptop');
    expect(resultText).not.toContain('brand');

    // Verify no exclusion message is shown
    const exclusionMessage = page.getByText(/no results found/i);
    await expect(exclusionMessage).not.toBeVisible();
  });

  test('should handle multiple excluded terms and display no results when all terms are excluded', async ({ page }) => {
    // Perform search with multiple exclusions
    const searchInput = page.getByPlaceholder('Search...');
    await searchInput.fill('laptop -brand -model');

    // Wait for search results to load
    await page.waitForResponse(response => 
      response.url().includes('/api/search') && response.status() === 200
    );

    // Verify search results container is visible
    const resultsContainer = page.getByRole('region', { name: /search results/i });
    await expect(resultsContainer).toBeVisible();

    // Verify no results are displayed
    const resultItems = page.getByRole('listitem');
    await expect(resultItems).toHaveCount(0);

    // Verify no results message is displayed
    const noResultsMessage = page.getByText(/no results found/i);
    await expect(noResultsMessage).toBeVisible();

    // Verify the search input still contains the full query
    await expect(searchInput).toHaveValue('laptop -brand -model');
  });
});
